#!/usr/bin/env python3
"""Run a named `run:` body straight out of .github/workflows/ci.yml.

The body is executed verbatim, in the step's own working-directory, with the
job's env applied, so what passes here is what the runner would execute.
"""
import os
import subprocess
import sys

import yaml

WF = "/home/ertval/code/project-modules/keel-multi-agent-pipeline/.github/workflows/ci.yml"
REPO = "/home/ertval/code/project-modules/keel-multi-agent-pipeline"


def steps():
    doc = yaml.safe_load(open(WF))
    for job_name, job in doc["jobs"].items():
        default_wd = job.get("defaults", {}).get("run", {}).get("working-directory")
        for step in job["steps"]:
            if "run" not in step:
                continue
            yield job_name, step.get("name", step.get("uses", "?")), step["run"], (
                step.get("working-directory") or default_wd
            ), job.get("env") or {}


def main():
    wanted = sys.argv[1:]
    for job_name, name, body, wd, env in steps():
        label = f"{job_name}/{name}"
        if wanted and not any(w in label for w in wanted):
            continue
        e = dict(os.environ)
        e.update({k: str(v) for k, v in env.items()})
        e["GITHUB_WORKSPACE"] = REPO
        cwd = os.path.join(REPO, wd) if wd else REPO
        print(f"\n{'=' * 78}\n### {label}   (cwd={cwd})\n{'=' * 78}", flush=True)
        rc = subprocess.call(["bash", "-e", "-c", body], cwd=cwd, env=e)
        print(f"--- {label}: exit {rc}", flush=True)
        if rc != 0:
            sys.exit(rc)


if __name__ == "__main__":
    main()

